draw:
var nTop = 1.0;
var nF = p.nfilm, nS = p.nsub, th = p.thick;
var flipTop = nF > nTop ? 1 : 0;
var flipBot = nS > nF ? 1 : 0;
var net = (flipTop + flipBot) % 2;

var padL = 44, padR = 14, padT = 16, padB = 30;
var gx0 = padL, gx1 = W - padR, gy0 = padT, gy1 = H - padB;
var lam0 = 400, lam1 = 700;
var X = function (lam) { return gx0 + (lam - lam0) / (lam1 - lam0) * (gx1 - gx0); };
var Y = function (v) { return gy1 - v * (gy1 - gy0); };

var refl = function (lam) {
  var delta = 2 * Math.PI * (2 * nF * th) / lam + (net ? Math.PI : 0);
  var c = Math.cos(delta / 2);
  return c * c;
};

ctx.lineWidth = 1;
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.lineTo(gx1, gy1);
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
for (var lam = 400; lam <= 700; lam += 50) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(X(lam), gy1); ctx.lineTo(X(lam), gy1 + 4); ctx.stroke();
  ctx.fillText(String(lam), X(lam), gy1 + 17);
}
ctx.fillText("wavelength in vacuum (nm)", (gx0 + gx1) / 2, gy1 + 29);
ctx.textAlign = "right";
ctx.fillText("1", gx0 - 6, gy0 + 5);
ctx.fillText("0", gx0 - 6, gy1 + 4);
ctx.save();
ctx.translate(14, (gy0 + gy1) / 2);
ctx.rotate(-Math.PI / 2);
ctx.textAlign = "center";
ctx.fillText("reflected", 0, 0);
ctx.restore();

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 300; i++) {
  var L = lam0 + (lam1 - lam0) * i / 300;
  var px = X(L), py = Y(refl(L));
  if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
}
ctx.stroke();

var scan = lam0 + (lam1 - lam0) * (0.5 - 0.5 * Math.cos(t * 0.7));
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(scan), gy0); ctx.lineTo(X(scan), gy1); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(scan), Y(refl(scan)), 4, 0, Math.PI * 2); ctx.fill();

var best = lam0, bestV = -1, dark = 0, darkV = 2;
for (var k = 0; k <= 300; k++) {
  var Lk = lam0 + (lam1 - lam0) * k / 300;
  var v = refl(Lk);
  if (v > bestV) { bestV = v; best = Lk; }
  if (v < darkV) { darkV = v; dark = Lk; }
}
out.note = "flips: " + (flipTop + flipBot) + "  |  2nt = " + (2 * nF * th).toFixed(0) +
  " nm  |  brightest near " + best.toFixed(0) + " nm, weakest near " + dark.toFixed(0) + " nm";
